<template><div class="ticket-list"><button v-for="ticket in tickets" :key="ticket.id" class="ticket-row" :class="{ selected: modelValue?.ticketTypeId === ticket.id }" :disabled="ticket.enabled === false || ticket.availableStock <= 0" @click="$emit('update:modelValue', { ticketTypeId: ticket.id, quantity: modelValue?.ticketTypeId === ticket.id ? modelValue.quantity : 1, ticket })"><span><b>{{ ticket.name }}</b><small>余票 {{ ticket.availableStock ?? '充足' }}</small></span><strong>¥{{ ticket.price }}</strong></button><div v-if="modelValue" class="quantity"><button @click="$emit('update:modelValue', { ...modelValue, quantity: Math.max(1, modelValue.quantity - 1) })"><AppIcon name="minus" size="16" /></button><b>{{ modelValue.quantity }}</b><button @click="$emit('update:modelValue', { ...modelValue, quantity: Math.min(modelValue.ticket.availableStock || 99, modelValue.quantity + 1) })"><AppIcon name="plus" size="16" /></button></div></div></template>
<script setup>
import AppIcon from './AppIcon.vue'
defineProps({ tickets: { type: Array, default: () => [] }, modelValue: Object }); defineEmits(['update:modelValue'])</script>
<style scoped>.ticket-list{position:relative}.ticket-row{width:100%;border:1px solid var(--line);background:#fff;border-radius:12px;padding:14px;display:flex;justify-content:space-between;text-align:left;margin-bottom:10px}.ticket-row.selected{border:2px solid var(--primary);background:var(--primary-soft)}.ticket-row:disabled{opacity:.45}.ticket-row span{display:flex;flex-direction:column;gap:6px}.ticket-row small{color:var(--muted)}.ticket-row strong{color:var(--primary);font-size:18px}.quantity{display:flex;align-items:center;gap:18px;justify-content:flex-end;margin:-2px 4px 12px}.quantity button{border:0;background:var(--primary-soft);color:var(--primary);font-size:20px;border-radius:8px;width:32px;height:32px}</style>
